111	/**
112	 * this function is a workaround to clean the output received by WSL2. Some time it sends output in utf16le, but we treat that as utf8,
113	 * this code just eliminate every 'empty' character
114	 * @param out the string to clean
115	 * @returns the string cleaned
116	 */
117	export function normalizeWSLOutput(out: string): string {
118	  let str = '';
119	  for (let i = 0; i < out.length; i++) {
120	    if (out.charCodeAt(i) !== 0) {
121	      str += out.charAt(i);
122	    }
123	  }
124	  return str;
125	}
