128	  args: string[],
129	  containersProvider?: string,
130	  options?: extensionApi.RunOptions,
131	): Promise<extensionApi.RunResult> {
132	  const finalOptions: extensionApi.RunOptions = { ...options };
133	
134	  if (containersProvider) {
135	    finalOptions.env = {
136	      ...(finalOptions.env ?? {}),
137	      CONTAINERS_MACHINE_PROVIDER: getProviderByLabel(containersProvider),
138	    };
139	  }
140	
141	  return extensionApi.process.exec(getPodmanCli(), args, finalOptions);
142	}
